// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        // keep the domain admissible: real actor, sane amount, no time overflow
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1e30);
        lockTime = bound(lockTime, 0, 1e18);

        // adversarial/log counterparty: c pushes AddMessage into it during Put
        LogSink sink = new LogSink();

        // drive the unit under test: configure the log target
        c.SetLogFile(address(sink));

        // general rule: after SetLogFile, ANY actor can deposit ANY amount
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

// minimal receiver that accepts the LogFile.AddMessage callback from c
contract LogSink {
    function AddMessage(address, uint256, string memory) public pure {}
}
